{
  "decision": "BLOCK",
  "findings": [
    {
      "severity": "high",
      "file": "cloud_pilot/multilingual/publication.py; cloud_pilot/multilingual/startup.py",
      "detail": "The only batch manifest is created with every article PENDING and all verdict counts zero. Research completion never updates it. Writing subsequently reads that stale manifest without checking its article statuses or version pointers, so the canonical batch record does not reflect the research baseline used for writing.",
      "required_fix": "Maintain a synchronized batch manifest with actual per-article research status, readiness, versions, completion commits and batch counts. Require writing startup to verify those entries against the accepted research records."
    },
    {
      "severity": "high",
      "file": "cloud_pilot/multilingual/__main__.py; cloud_pilot/multilingual/source_cache.py",
      "detail": "If one protected source transfer fails, the exception handler starts or restarts research and persists a failure for both topics. This can invalidate an unrelated accepted research head. It also records only the generic label PROTECTED_SOURCE_TRANSFER rather than the failing source ID and URL.",
      "required_fix": "Propagate the affected article and exact source identity from the transfer failure. Persist failure and partial evidence only for that article; preserve unaffected research heads and readiness."
    },
    {
      "severity": "high",
      "file": "cloud_pilot/multilingual/publication.py",
      "detail": "The multilingual delivery commit contains 73 files, but verify_files requests /commits/{sha} without handling GitHub's paginated file list and then requires all files in the first response. The branch is updated before this verification, so a successful bundle write can be reported as a failure and leave its publication fence active.",
      "required_fix": "Retrieve and verify every changed-file page, including exact paths, blob hashes and parent, and test the real transport with a 73-file commit and a recovery after an interrupted verification."
    }
  ],
  "human_reviewed": false,
  "publish_approved": false
}
